import React, { useState } from 'react';

const DesignSystem = () => {
  const [tokens, setTokens] = useState({
    primaryColor: '#007bff',
    fontSize: '16px',
    spacing: '8px'
  });

  const updateToken = (tokenName, value) => {
    setTokens(prev => ({
      ...prev,
      [tokenName]: value
    }));
  };

  return (
    <div>
      <section>
        <h2>Design Tokens</h2>
        <p>Primary Color: {tokens.primaryColor}</p>
        <p>Font Size: {tokens.fontSize}</p>
        <p>Spacing: {tokens.spacing}</p>
      </section>
      <section>
        <h2>Token Controls</h2>
        <div>
          <label>Primary Color:</label>
          <input 
            type="color" 
            value={tokens.primaryColor} 
            onChange={(e) => updateToken('primaryColor', e.target.value)}
          />
        </div>
        <div>
          <label>Font Size:</label>
          <input 
            type="text" 
            value={tokens.fontSize} 
            onChange={(e) => updateToken('fontSize', e.target.value)}
          />
        </div>
        <div>
          <label>Spacing:</label>
          <input 
            type="text" 
            value={tokens.spacing} 
            onChange={(e) => updateToken('spacing', e.target.value)}
          />
        </div>
      </section>
    </div>
  );
};

